pub fn is_sorted(arr: &Vec<i32>) -> bool {
    // Iterate through the array and check each adjacent pair.
    // If any element is less than the previous one, it's not nondecreasing.
    for i in 1..arr.len() {
        if arr[i] < arr[i - 1] {
            return false;
        }
    }
    true
}

